package main

import "testing"

// TestUpstreamBase pins the MELLIFERA_SHIKIMORI_UPSTREAM seam's three
// branches: an empty value falls back to the production origin (every literal
// template assertion in this suite depends on that default), an override
// replaces it verbatim, and a trailing slash is trimmed so the baked
// templates never double the separator. The one REAL read happens once at
// process start (apiBase's initializer); this exercises the pure reader.
func TestUpstreamBase(t *testing.T) {
	for _, tc := range []struct {
		name, env, want string
	}{
		{"empty env falls back to the production origin", "", defaultAPIBase},
		{"override replaces the origin verbatim", "http://127.0.0.1:9377", "http://127.0.0.1:9377"},
		{"override trims a trailing slash", "http://127.0.0.1:9377/", "http://127.0.0.1:9377"},
		{"slash-only value falls back", "///", defaultAPIBase},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv(upstreamEnvVar, tc.env)
			if got := upstreamBase(); got != tc.want {
				t.Errorf("upstreamBase() = %q, want %q", got, tc.want)
			}
		})
	}
}
